// <auto-imports> — generated by wire.mjs, do not edit by hand
import { BRIDGE_GRANT_PREFIX, BRIDGE_ROLL_TRACE_PREFIX, BRIDGE_TRACE_PREFIX, BRIDGE_TRACE_SETTING, MODULE_ID } from "./constants.js";
import { bridgeRuntimeState, endItemUseAdvantageMode, mobileItemUseAdvantageMode } from "./map.js";
import { ok } from "./users.js";
// </auto-imports>
// Trace / grant logging + result summaries — extracted from mobile-bridge.js.

export function bridgeTraceEnabled() {
  try {
    return game.settings.get(MODULE_ID, BRIDGE_TRACE_SETTING) === true;
  } catch {
    return false;
  }
}

export function bridgeTrace(...args) {
  if (!bridgeTraceEnabled()) return;
  console.log(BRIDGE_TRACE_PREFIX, ...args);
}

export function bridgeTraceSkip(reason, message) {
  if (!bridgeTraceEnabled()) return;
  console.warn(`${BRIDGE_TRACE_PREFIX} SKIP ${reason}`, message);
}

export function rollAdvantageTrace(...args) {
  console.log(BRIDGE_ROLL_TRACE_PREFIX, ...args);
}

export function rollAdvantageTraceVerbose(...args) {
  if (!bridgeTraceEnabled()) return;
  console.log(BRIDGE_ROLL_TRACE_PREFIX, ...args);
}

/** Always-on grant/approval diagnostics (filter console: bag-of-worlds:grant). */
export function grantLog(...args) {
  console.log(BRIDGE_GRANT_PREFIX, ...args.map(grantLogArg));
}

export function grantWarn(...args) {
  console.warn(BRIDGE_GRANT_PREFIX, ...args.map(grantLogArg));
}

export function grantError(...args) {
  console.error(BRIDGE_GRANT_PREFIX, ...args.map(grantLogArg));
}

/** Flatten objects to JSON so pasted console logs are readable without expanding. */
export function grantLogArg(value) {
  if (value == null) return value;
  if (value instanceof Error) {
    return { name: value.name, message: value.message, stack: value.stack?.split("\n").slice(0, 6) };
  }
  if (typeof value !== "object") return value;
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

/** Compact snapshot of an Item document or plain item data for grant debugging. */
export function summarizeGrantItem(docOrData, label = "item") {
  if (!docOrData) return { label, missing: true };
  const isDoc = typeof docOrData.documentName === "string" || typeof docOrData.toObject === "function";
  const raw = isDoc && typeof docOrData.toObject === "function" ? docOrData.toObject() : docOrData;
  const system = raw?.system ?? {};
  const activities = system.activities;
  let activitySummary = null;
  if (activities && typeof activities === "object") {
    const entries = Object.entries(activities);
    activitySummary = {
      count: entries.length,
      types: entries.map(([, a]) => a?.type ?? "?").slice(0, 8)
    };
  }
  const damageParts = system.damage?.parts ?? system.damage?.base ?? null;
  return {
    label,
    name: raw?.name ?? null,
    type: raw?.type ?? null,
    uuid: isDoc ? (docOrData.uuid ?? null) : null,
    pack: isDoc ? (docOrData.pack ?? null) : (raw?.pack ?? null),
    id: raw?._id ?? (isDoc ? docOrData.id : null) ?? null,
    img: raw?.img ? String(raw.img).slice(0, 80) : null,
    consumableType: system.type?.value ?? null,
    consumableSubtype: system.type?.subtype ?? null,
    weaponType: system.type?.value ?? (raw?.type === "weapon" ? system.type?.value : null),
    quantity: system.quantity ?? null,
    attunement: system.attunement ?? system.attuned ?? null,
    attuned: system.attuned === true,
    attunementRequired: system.attunement === "required",
    equipped: system.equipped ?? null,
    activities: activitySummary,
    hasDamageParts: Array.isArray(damageParts) ? damageParts.length > 0 : !!damageParts,
    damagePreview: damageParts
      ? (typeof damageParts === "object" ? JSON.stringify(damageParts).slice(0, 160) : String(damageParts).slice(0, 160))
      : null,
    descriptionLen: String(system.description?.value ?? "").length,
    keys: raw && typeof raw === "object" ? Object.keys(raw).slice(0, 20) : []
  };
}

export function summarizeRollConfig(config) {
  if (!config || typeof config !== "object") return config;
  const out = {};
  if ("advantage" in config) out.advantage = config.advantage;
  if ("disadvantage" in config) out.disadvantage = config.disadvantage;
  if ("skill" in config) out.skill = config.skill;
  if ("ability" in config) out.ability = config.ability;
  if ("type" in config) out.type = config.type;
  if (config.rolls?.[0]?.options) {
    out.rolls0options = { ...config.rolls[0].options };
  }
  if (config.event) {
    out.event = { altKey: !!config.event.altKey, ctrlKey: !!config.event.ctrlKey };
  }
  out.configKeys = Object.keys(config).filter((k) => k !== "event").slice(0, 12);
  return out;
}

export function logRollAdvantageContext(rollKind, fields) {
  clearStaleItemUseAdvantageForMobileRoll(rollKind);
  const sessionMode = mobileItemUseAdvantageMode();
  const rt = bridgeRuntimeState();
  const payload = {
    ...fields,
    itemUseSessionMode: sessionMode,
    itemUseCleanupPending: !!rt.itemUseAdvantageCleanupTimer
  };
  rollAdvantageTrace(rollKind, payload);
}

export function clearStaleItemUseAdvantageForMobileRoll(rollKind) {
  const sessionMode = mobileItemUseAdvantageMode();
  if (sessionMode === 0) return;
  const rt = bridgeRuntimeState();
  rollAdvantageTrace("clear stale itemUseAdvantageMode before mobile roll", {
    rollKind,
    sessionMode,
    cleanupPending: !!rt.itemUseAdvantageCleanupTimer
  });
  if (rt.itemUseAdvantageCleanupTimer) {
    window.clearTimeout(rt.itemUseAdvantageCleanupTimer);
    delete rt.itemUseAdvantageCleanupTimer;
  }
  endItemUseAdvantageMode();
}

export function summarizeBridgeResult(action, response) {
  if (!response) return "null";
  if (!response.ok) {
    return `ok=false code=${response.error?.code ?? "?"} msg=${response.error?.message ?? ""}`;
  }
  const r = response.result;
  if (!r) return "ok=true empty result";
  if (action === "actor.inventory.list") {
    return `ok=true items=${r.items?.length ?? 0} itemCount=${r.itemCount ?? "?"}`;
  }
  if (action === "scene.viewport.snapshot") {
    const jpeg = r.debug?.jpegBytes ?? r.imageBase64?.length ?? 0;
    const tpl = r.template;
    const tplInfo = tpl
      ? `${tpl.shape}@${tpl.xInCrop},${tpl.yInCrop} r=${tpl.radiusPx ?? 0}`
      : "none";
    return `ok=true ${r.widthPx ?? 0}x${r.heightPx ?? 0}px jpeg=${jpeg} template=${tplInfo} err=${r.error ?? ""}`;
  }
  if (action === "actor.token.placement") {
    return `ok=true hasToken=${r.hasTokenOnScene ?? false} reason=${r.reason ?? ""}`;
  }
  if (action === "health.ping") {
    return `ok=true v=${r.moduleVersion ?? "?"}`;
  }
  if (action === "chat.log.get") {
    return `ok=true messages=${r.messages?.length ?? 0} hasMore=${r.hasMore ?? false}`;
  }
  return "ok=true";
}
